INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7261516, 1129493, 163430, '<td valign="top">The shadow reminds me of a character from the cartoon "Samurai Jack".</td>', 'The shadow reminds me of a character from the cartoon "Samurai Jack".', '2014-09-10 04:34:26.000000', NULL, 1),
(7261518, 1129494, 163430, '<td valign="top">I couldn''t stand another hour of daylight</td>', 'I couldn''t stand another hour of daylight', '2014-09-10 04:45:10.000000', NULL, 1),
(7261519, 1129491, 53056, '<td valign="top">Like it!</td>', 'Like it!', '2014-09-10 05:01:26.000000', NULL, 1),
(7261538, 1129371, 113156, '<td valign="top">Bring on the toast, a splatter of a shot.</td>', 'Bring on the toast, a splatter of a shot.', '2014-09-10 08:18:42.000000', NULL, 1),
(7261540, 1129455, 113156, '<td valign="top">Splendid light and photo.</td>', 'Splendid light and photo.', '2014-09-10 08:20:55.000000', NULL, 1),
(7261544, 1129441, 113156, '<td valign="top">Great compo, attractive shot.</td>', 'Great compo, attractive shot.', '2014-09-10 09:31:35.000000', NULL, 1),
(7261545, 1129510, 113156, '<td valign="top">Zenhatten, things are happening that I like, thanks.</td>', 'Zenhatten, things are happening that I like, thanks.', '2014-09-10 09:33:17.000000', NULL, 1),
(7261546, 1129502, 113156, '<td valign="top">Wonderful, love the vegetation in the mirror and the rest.</td>', 'Wonderful, love the vegetation in the mirror and the rest.', '2014-09-10 09:35:29.000000', NULL, 1),
(7261549, 1129520, 113156, '<td valign="top">Off to see the wizard......</td>', 'Off to see the wizard......', '2014-09-10 09:38:23.000000', NULL, 1),
(7261550, 1129446, 113156, '<td valign="top">Just fabulous, a big well done.</td>', 'Just fabulous, a big well done.', '2014-09-10 09:40:24.000000', NULL, 1),
(7261552, 1129103, 113156, '<td valign="top">Didn''t need cutting, glad you took this though.7</td>', 'Didn''t need cutting, glad you took this though.7', '2014-09-10 09:43:11.000000', NULL, 1),
(7261562, 1129509, 117474, '<td valign="top">I think the flag ebbs some mystery from the image, but the tones are really wonderful!</td>', 'I think the flag ebbs some mystery from the image, but the tones are really wonderful!', '2014-09-10 10:02:19.000000', NULL, 1),
(7261567, 1129502, 16148, '<td valign="top">Fantastic!  You left us some room to explore.</td>', 'Fantastic!  You left us some room to explore.', '2014-09-10 10:06:38.000000', NULL, 1),
(7261568, 1129089, 117474, '<td valign="top">It almost looks like the phases of the moon. I like it. Nice abstract!</td>', 'It almost looks like the phases of the moon. I like it. Nice abstract!', '2014-09-10 10:06:45.000000', NULL, 1),
(7261569, 1129509, 16148, '<td valign="top">My top pick.  Beautiful toning and story.</td>', 'My top pick.  Beautiful toning and story.', '2014-09-10 10:07:31.000000', NULL, 1),
(7261571, 1129421, 117474, '<td valign="top">Two stories in one. Superb angle.</td>', 'Two stories in one. Superb angle.', '2014-09-10 10:08:20.000000', NULL, 1),
(7261572, 1129488, 16148, '<td valign="top">Nicely caught!</td>', 'Nicely caught!', '2014-09-10 10:09:01.000000', NULL, 1),
(7261574, 1129446, 117474, '<td valign="top">Surreal shadows.</td>', 'Surreal shadows.', '2014-09-10 10:09:46.000000', NULL, 1),
(7261575, 1129103, 117474, '<td valign="top">Like the contrast with the dog.</td>', 'Like the contrast with the dog.', '2014-09-10 10:11:44.000000', NULL, 1),
(7261576, 1129493, 16148, '<td valign="top">The classic fork and shadow but your fingerprints are all over this.  Great texture and tones on the flat surface.  Old wall paper?</td>', 'The classic fork and shadow but your fingerprints are all over this.  Great texture and tones on the flat surface.  Old wall paper?', '2014-09-10 10:12:14.000000', NULL, 1),
(7261577, 1129282, 16148, '<td valign="top">I like the negative space across the top.  Nice composition with stretched shadows.</td>', 'I like the negative space across the top.  Nice composition with stretched shadows.', '2014-09-10 10:13:32.000000', NULL, 1),
(7261578, 1129495, 117474, '<td valign="top">I like to use shadows as obscure means of bordering images. I dig your vertical letterbox! Bus also the textures and contrast here.</td>', 'I like to use shadows as obscure means of bordering images. I dig your vertical letterbox! Bus also the textures and contrast here.', '2014-09-10 10:14:12.000000', NULL, 1),
(7261579, 1129371, 16148, '<td valign="top">The rated PG version of a classic tale.  Nice!</td>', 'The rated PG version of a classic tale.  Nice!', '2014-09-10 10:14:33.000000', NULL, 1),
(7261580, 1129520, 117474, '<td valign="top">Lurve this. What a perfect colour road for this image.</td>', 'Lurve this. What a perfect colour road for this image.', '2014-09-10 10:14:57.000000', NULL, 1),
(7261581, 1129274, 117474, '<td valign="top">I like the sense of... Anonymity here. Perfect balance!</td>', 'I like the sense of... Anonymity here. Perfect balance!', '2014-09-10 10:17:03.000000', NULL, 1),
(7261582, 1129472, 16148, '<td valign="top">Did you take this while you were sleeping?  Nightmare comes to mind for me.  Terrific catch!</td>', 'Did you take this while you were sleeping?  Nightmare comes to mind for me.  Terrific catch!', '2014-09-10 10:17:29.000000', NULL, 1),
(7261583, 1129185, 117474, '<td valign="top">Really like the simplicity, grain and shape. Nothing wrong with this at all!</td>', 'Really like the simplicity, grain and shape. Nothing wrong with this at all!', '2014-09-10 10:18:16.000000', NULL, 1),
(7261584, 1129500, 16148, '<td valign="top">Bold lines and strong contrast make this pop.  Nice!</td>', 'Bold lines and strong contrast make this pop.  Nice!', '2014-09-10 10:18:20.000000', NULL, 1),
(7261585, 1129391, 13077, '<td valign="top">I like the aesthetic. I have a feeling this will get beat up by voters but a lot can be said for simplicity and an unusual portrayal of this scene. Might make an interesting framed print to complement modern decor.</td>', 'I like the aesthetic. I have a feeling this will get beat up by voters but a lot can be said for simplicity and an unusual portrayal of this scene. Might make an interesting framed print to complement modern decor.', '2014-09-10 10:20:33.000000', NULL, 1),
(7261587, 1129487, 16148, '<td valign="top">I appreciate your restraint from pushing the contrast to much.  This has a nice soft feel reminiscent of film.</td>', 'I appreciate your restraint from pushing the contrast to much.  This has a nice soft feel reminiscent of film.', '2014-09-10 10:20:54.000000', NULL, 1),
(7261588, 1129278, 117474, '<td valign="top">Could almost be a family portrait.</td>', 'Could almost be a family portrait.', '2014-09-10 10:21:54.000000', NULL, 1),
(7261591, 1129474, 13077, '<td valign="top">This scene has a lot of potential - I would have recommended moving closer, eliminating the plant in the foreground and visually separating the shadow from the coat hanger. If it was yours to manipulate, I think it might also have looked better with the extension cords removed to make it a study of the vertical, diagonal and horizontal lines. The way the shadows become double when they hit the window is very interesting.</td>', 'This scene has a lot of potential - I would have recommended moving closer, eliminating the plant in the foreground and visually separating the shadow from the coat hanger. If it was yours to manipulate, I think it might also have looked better with the extension cords removed to make it a study of the vertical, diagonal and horizontal lines. The way the shadows become double when they hit the window is very interesting.', '2014-09-10 10:27:10.000000', NULL, 1),
(7261595, 1129373, 13077, '<td valign="top">Looks like a nice place to stroll around and take pictures. I like the soft shadows.<br/>The composition might have been improved if you had moved around a bit paying attention to where the lamp at the top of the frame ends up in relation to the angles in the wall.</td>', 'Looks like a nice place to stroll around and take pictures. I like the soft shadows.The composition might have been improved if you had moved around a bit paying attention to where the lamp at the top of the frame ends up in relation to the angles in the wall.', '2014-09-10 10:36:31.000000', NULL, 1),
(7261597, 1129516, 13077, '<td valign="top">Looks like such an interesting old barn. Nicely done with the fill light on the front of the truck. Excellent photo overall.</td>', 'Looks like such an interesting old barn. Nicely done with the fill light on the front of the truck. Excellent photo overall.', '2014-09-10 10:42:00.000000', NULL, 1),
(7261598, 1129431, 13077, '<td valign="top">Well done with the dismal, gritty feel and harsh lighting.</td>', 'Well done with the dismal, gritty feel and harsh lighting.', '2014-09-10 10:42:52.000000', NULL, 1),
(7261601, 1129488, 13077, '<td valign="top">Very well composed. I like the tones and the dark colors. The processing really makes it look like a enlarger print.</td>', 'Very well composed. I like the tones and the dark colors. The processing really makes it look like a enlarger print.', '2014-09-10 10:45:07.000000', NULL, 1),
(7261603, 1129466, 13077, '<td valign="top">I like your concept, and I even like the composition, but in my opinion the color cast doesn''t fit very well here. I''m guessing it was handheld at a pretty low shutter speed so the sharpness isn''t going to be the greatest, but the details in the asphalt at the foreground would have looked better sharp.</td>', 'I like your concept, and I even like the composition, but in my opinion the color cast doesn''t fit very well here. I''m guessing it was handheld at a pretty low shutter speed so the sharpness isn''t going to be the greatest, but the details in the asphalt at the foreground would have looked better sharp.', '2014-09-10 10:48:14.000000', NULL, 1),
(7261606, 1129448, 13077, '<td valign="top">Simple enough concept, and I like the tones, but the amount of empty sidewalk in the frame isn''t adding much value in my opinion.</td>', 'Simple enough concept, and I like the tones, but the amount of empty sidewalk in the frame isn''t adding much value in my opinion.', '2014-09-10 10:49:52.000000', NULL, 1),
(7261607, 1129317, 13077, '<td valign="top">Well chosen subject, the complex shadow is interesting. There are a few minor flaws that could have been improved in processing - the very bottom right corner has something dark in the frame, and there''s a speck right under the pedestal and a white line near the bottom left corner. The shadow itself has a lighter patch near the shoulders of the trumpeter, this could have been selectively darkened pretty easily.</td>', 'Well chosen subject, the complex shadow is interesting. There are a few minor flaws that could have been improved in processing - the very bottom right corner has something dark in the frame, and there''s a speck right under the pedestal and a white line near the bottom left corner. The shadow itself has a lighter patch near the shoulders of the trumpeter, this could have been selectively darkened pretty easily.', '2014-09-10 10:52:45.000000', NULL, 1),
(7261609, 1129291, 13077, '<td valign="top">When you have a flat plane like this wood surface, it''s usually pretty easy to get the camera parallel to it so the whole thing is in focus. Your concept of having the flower out of focus in the foreground while the shadow is in focus is pretty cool.</td>', 'When you have a flat plane like this wood surface, it''s usually pretty easy to get the camera parallel to it so the whole thing is in focus. Your concept of having the flower out of focus in the foreground while the shadow is in focus is pretty cool.', '2014-09-10 10:56:53.000000', NULL, 1),
(7261610, 1129394, 13077, '<td valign="top">I really like this one. Great tones and composition, and it looks like you made use of the new textures rule too.</td>', 'I really like this one. Great tones and composition, and it looks like you made use of the new textures rule too.', '2014-09-10 10:57:40.000000', NULL, 1),
(7261612, 1129472, 13077, '<td valign="top">This is striking with the patterns, contrast and the clean black background. It''s very mysterious - Is that someone riding a horse?<br/>I imagine you will probably get beat up on the scores for having a confusing almost abstract photo, but it sure is interesting. There''s so much to it.</td>', 'This is striking with the patterns, contrast and the clean black background. It''s very mysterious - Is that someone riding a horse?I imagine you will probably get beat up on the scores for having a confusing almost abstract photo, but it sure is interesting. There''s so much to it.', '2014-09-10 11:04:00.000000', NULL, 1),
(7261614, 1129459, 13077, '<td valign="top">I like the warm tones in contrast to the menacing shadow and concept.</td>', 'I like the warm tones in contrast to the menacing shadow and concept.', '2014-09-10 11:06:27.000000', NULL, 1),
(7261615, 1129446, 13077, '<td valign="top">I''m confused looking at this, but as a whole I really like it. This is definitely one to print and hang up.</td>', 'I''m confused looking at this, but as a whole I really like it. This is definitely one to print and hang up.', '2014-09-10 11:08:11.000000', NULL, 1),
(7261616, 1129468, 13077, '<td valign="top">Very well done overall. Interesting take on a silhouette, and excellent job keeping clean gradiations and tones. I like the border as well.</td>', 'Very well done overall. Interesting take on a silhouette, and excellent job keeping clean gradiations and tones. I like the border as well.', '2014-09-10 11:08:50.000000', NULL, 1),
(7261617, 1129509, 13077, '<td valign="top">Very cool. I like the overall environment of it.</td>', 'Very cool. I like the overall environment of it.', '2014-09-10 11:11:57.000000', NULL, 1),
(7261618, 1129381, 13077, '<td valign="top">This is really cool, and I can''t figure out how you did it so I''m looking forward to seeing at the end of the challenge.</td>', 'This is really cool, and I can''t figure out how you did it so I''m looking forward to seeing at the end of the challenge.', '2014-09-10 11:12:30.000000', NULL, 1),
(7261622, 1129451, 13077, '<td valign="top">Nicely done. Just enough is in focus while keeping the emphasis on the shadow which looks uniformly sharp. I like your title, it makes me think the way the shadows from the fly''s legs fall off could be its ghost getting ready to be an invisible force of annoyance and drive someone crazy. lol</td>', 'Nicely done. Just enough is in focus while keeping the emphasis on the shadow which looks uniformly sharp. I like your title, it makes me think the way the shadows from the fly''s legs fall off could be its ghost getting ready to be an invisible force of annoyance and drive someone crazy. lol', '2014-09-10 11:16:59.000000', NULL, 1),
(7261624, 1129325, 13077, '<td valign="top">Interesting, it''s about to be fall here. I like the way the stalks of the plant cast shadows when lit from that angle, but the texture on the ground is harsh to look at when photographed this way.</td>', 'Interesting, it''s about to be fall here. I like the way the stalks of the plant cast shadows when lit from that angle, but the texture on the ground is harsh to look at when photographed this way.', '2014-09-10 11:19:31.000000', NULL, 1),
(7261626, 1129332, 13077, '<td valign="top">Is he peeing? lol</td>', 'Is he peeing? lol', '2014-09-10 11:20:21.000000', NULL, 1),
(7261627, 1129515, 13077, '<td valign="top">Interesting take. I think it would have worked better with a square crop and shot directly at the fence so the lines would be straight.</td>', 'Interesting take. I think it would have worked better with a square crop and shot directly at the fence so the lines would be straight.', '2014-09-10 11:21:22.000000', NULL, 1),
(7261628, 1129437, 13077, '<td valign="top">Well done. Your title and the way the center of the cross falls on the HB makes me try to read deeper into it, but I''m not familiar enough with history and Christianity to know if that is significant.</td>', 'Well done. Your title and the way the center of the cross falls on the HB makes me try to read deeper into it, but I''m not familiar enough with history and Christianity to know if that is significant.', '2014-09-10 11:26:18.000000', NULL, 1),
(7261630, 1129492, 13077, '<td valign="top">Interesting - I like the textures of the wall and the light fall-off and focus fall-off in the shadow is very cool.</td>', 'Interesting - I like the textures of the wall and the light fall-off and focus fall-off in the shadow is very cool.', '2014-09-10 11:27:45.000000', NULL, 1),
(7261631, 1129452, 13077, '<td valign="top">Chimping?<br/>If this was meant to be a serious photo, I would recommend cropping to remove the dark part on the very left and the metal thing on the right.</td>', 'Chimping?If this was meant to be a serious photo, I would recommend cropping to remove the dark part on the very left and the metal thing on the right.', '2014-09-10 11:28:57.000000', NULL, 1),
(7261633, 1129298, 13077, '<td valign="top">I like the atmosphere, but you could have gotten a lot of the same without as much empty dark space by shooting at an angle much closer to the faces of the people walking across the street. That way you could see some details of the people, and if you slightly increased the exposure depending on how bright the car''s headlights were you might take in a little more of the street scene.</td>', 'I like the atmosphere, but you could have gotten a lot of the same without as much empty dark space by shooting at an angle much closer to the faces of the people walking across the street. That way you could see some details of the people, and if you slightly increased the exposure depending on how bright the car''s headlights were you might take in a little more of the street scene.', '2014-09-10 11:30:47.000000', NULL, 1),
(7261634, 1129520, 13077, '<td valign="top">This is really cool. Would make a good print because it''s so intriguing. The plants themselves do seem soft, though.</td>', 'This is really cool. Would make a good print because it''s so intriguing. The plants themselves do seem soft, though.', '2014-09-10 11:32:36.000000', NULL, 1),
(7261635, 1129465, 13077, '<td valign="top">The shadow is very striking with the angle you shot it at - did you try one with the sun right behind the tip of the triangle?</td>', 'The shadow is very striking with the angle you shot it at - did you try one with the sun right behind the tip of the triangle?', '2014-09-10 11:34:37.000000', NULL, 1),
(7261636, 1129511, 13077, '<td valign="top">I like the grit and the way the person looks distorted in the shadow.</td>', 'I like the grit and the way the person looks distorted in the shadow.', '2014-09-10 11:35:06.000000', NULL, 1),
(7261638, 1129495, 13077, '<td valign="top">Very well done overall. Great lighting and detail in the surfaces.</td>', 'Very well done overall. Great lighting and detail in the surfaces.', '2014-09-10 11:35:38.000000', NULL, 1),
(7261639, 1129243, 13077, '<td valign="top">This looks very flat overall and I don''t see the shadows theme at all.</td>', 'This looks very flat overall and I don''t see the shadows theme at all.', '2014-09-10 11:36:27.000000', NULL, 1),
(7261640, 1129278, 13077, '<td valign="top">I really like this. The only thing I could suggest is maybe crop from the bottom a bit more.</td>', 'I really like this. The only thing I could suggest is maybe crop from the bottom a bit more.', '2014-09-10 11:37:22.000000', NULL, 1),
(7261644, 1129513, 13077, '<td valign="top">Cool concept. I think a little more sharpening could have improved it though.</td>', 'Cool concept. I think a little more sharpening could have improved it though.', '2014-09-10 11:46:11.000000', NULL, 1),
(7261645, 1129503, 13077, '<td valign="top">Yes it does. lol</td>', 'Yes it does. lol', '2014-09-10 11:46:28.000000', NULL, 1),
(7261646, 1129225, 13077, '<td valign="top">Nice scene, and good job getting a fair amount of sharpness from very low light conditions.</td>', 'Nice scene, and good job getting a fair amount of sharpness from very low light conditions.', '2014-09-10 11:47:22.000000', NULL, 1),
(7261647, 1129093, 13077, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2014-09-10 11:47:38.000000', NULL, 1),
(7261648, 1129380, 13077, '<td valign="top">I don''t find anything particularly interesting about this - there might have been a better camera angle and composition for this scene.</td>', 'I don''t find anything particularly interesting about this - there might have been a better camera angle and composition for this scene.', '2014-09-10 11:48:35.000000', NULL, 1),
(7261658, 1129504, 13077, '<td valign="top">This is very interesting, I''m looking forwad to the end to see how you shot it.</td>', 'This is very interesting, I''m looking forwad to the end to see how you shot it.', '2014-09-10 12:02:24.000000', NULL, 1),
(7261659, 1129486, 13077, '<td valign="top">I like this a lot. Very striking light and a beautiful scene.</td>', 'I like this a lot. Very striking light and a beautiful scene.', '2014-09-10 12:02:48.000000', NULL, 1),
(7261661, 1129487, 13077, '<td valign="top">Powerful image. Good control of the dynamic range and I like the soft feel.</td>', 'Powerful image. Good control of the dynamic range and I like the soft feel.', '2014-09-10 12:03:20.000000', NULL, 1),
(7261663, 1129502, 13077, '<td valign="top">Interesting sort of abstract, nice gloomy environment to it.</td>', 'Interesting sort of abstract, nice gloomy environment to it.', '2014-09-10 12:03:59.000000', NULL, 1),
(7261664, 1129426, 13077, '<td valign="top">No bugs on that branch, huh little dragonfly? lol<br/>I like the tones and shapes, very attractive photo overall.</td>', 'No bugs on that branch, huh little dragonfly? lolI like the tones and shapes, very attractive photo overall.', '2014-09-10 12:05:13.000000', NULL, 1),
(7261665, 1129371, 13077, '<td valign="top">Technically there are a lot of things that could be considered flaws but presented this way it works pretty well.</td>', 'Technically there are a lot of things that could be considered flaws but presented this way it works pretty well.', '2014-09-10 12:05:50.000000', NULL, 1),
(7261666, 1129357, 13077, '<td valign="top">Good angle and composition. I like the crop as well.</td>', 'Good angle and composition. I like the crop as well.', '2014-09-10 12:06:07.000000', NULL, 1),
(7261667, 1129424, 13077, '<td valign="top">Looks like a nice place for a walk. Very good colors and composition, and I like the way you kept detail in the shadows.</td>', 'Looks like a nice place for a walk. Very good colors and composition, and I like the way you kept detail in the shadows.', '2014-09-10 12:06:52.000000', NULL, 1),
(7261669, 1129461, 13077, '<td valign="top">There are certainly shadows, but this photo doesn''t really appeal to me. The hiker isn''t really in sharp focus and I don''t care for his positioning relative to the scene. I would have liked to see the color version as well, not sure the B&amp;W conversion does this any favors.</td>', 'There are certainly shadows, but this photo doesn''t really appeal to me. The hiker isn''t really in sharp focus and I don''t care for his positioning relative to the scene. I would have liked to see the color version as well, not sure the B&W conversion does this any favors.', '2014-09-10 12:08:13.000000', NULL, 1),
(7261670, 1129186, 13077, '<td valign="top">Very good lighting and sharp focus in the right places on the flat surface. I like it a lot.</td>', 'Very good lighting and sharp focus in the right places on the flat surface. I like it a lot.', '2014-09-10 12:10:13.000000', NULL, 1),
(7261671, 1129491, 13077, '<td valign="top">This is really cool. I like the soft textures on the flat surface and the angle of the knife and the light are perfect. Very well done.</td>', 'This is really cool. I like the soft textures on the flat surface and the angle of the knife and the light are perfect. Very well done.', '2014-09-10 12:10:46.000000', NULL, 1),
(7261673, 1129445, 13077, '<td valign="top">This strikes me as a potentially good book cover photo. Very dramatic scene and well exposed. I would probably suggest a lower crop from the top, though.</td>', 'This strikes me as a potentially good book cover photo. Very dramatic scene and well exposed. I would probably suggest a lower crop from the top, though.', '2014-09-10 12:12:04.000000', NULL, 1),
(7261674, 1129450, 13077, '<td valign="top">I don''t find anything interesting about this photo - maybe if there was something in the grass to be a subject rather than just the long shadow. Also the grass could use a bit more sharpening.</td>', 'I don''t find anything interesting about this photo - maybe if there was something in the grass to be a subject rather than just the long shadow. Also the grass could use a bit more sharpening.', '2014-09-10 12:12:48.000000', NULL, 1),
(7261676, 1129274, 13077, '<td valign="top">I like the composition, and just enough detail visible in the children walking while keeping the shadows sharp and dark.</td>', 'I like the composition, and just enough detail visible in the children walking while keeping the shadows sharp and dark.', '2014-09-10 12:14:00.000000', NULL, 1),
(7261695, 1129487, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-09-10 12:47:47.000000', NULL, 1),
(7261696, 1129426, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-09-10 12:48:21.000000', NULL, 1),
(7261698, 1129509, 16046, '<td valign="top">Top  3</td>', 'Top  3', '2014-09-10 12:49:10.000000', NULL, 1),
(7261701, 1129431, 16046, '<td valign="top">Front page stuff</td>', 'Front page stuff', '2014-09-10 12:49:57.000000', NULL, 1),
(7261703, 1129516, 16046, '<td valign="top">Front page stuff</td>', 'Front page stuff', '2014-09-10 12:51:01.000000', NULL, 1),
(7261711, 1129494, 13077, '<td valign="top">Such good light. This looks great.</td>', 'Such good light. This looks great.', '2014-09-10 13:22:35.000000', NULL, 1),
(7261712, 1129487, 138253, '<td valign="top">Expect this on the front page. great light - the glow is nice.</td>', 'Expect this on the front page. great light - the glow is nice.', '2014-09-10 13:22:56.000000', NULL, 1),
(7261713, 1129500, 138253, '<td valign="top">figure this for at least top10</td>', 'figure this for at least top10', '2014-09-10 13:23:31.000000', NULL, 1),
