(7261727, 1129089, 13077, '<td valign="top">Very cool almost abstract photo with great tones and just the right amount of motion blur. I would print this for sure if I were you.</td>', 'Very cool almost abstract photo with great tones and just the right amount of motion blur. I would print this for sure if I were you.', '2014-09-10 13:42:21.000000', NULL, 1),
(7261728, 1129103, 13077, '<td valign="top">This comes across as a practice shot for trying a new processing technique - the processing looks great, but the photo itself could probably have been thought out and composed better.</td>', 'This comes across as a practice shot for trying a new processing technique - the processing looks great, but the photo itself could probably have been thought out and composed better.', '2014-09-10 13:44:07.000000', NULL, 1),
