(7262030, 1129446, 163081, '<td valign="top">Very special. I love it. As thumbnail it looks like a dragonfly in the sky. <br/>Hopefully you get a good final score. an 8 from me.</td>', 'Very special. I love it. As thumbnail it looks like a dragonfly in the sky. Hopefully you get a good final score. an 8 from me.', '2014-09-11 12:09:16.000000', NULL, 1),
(7262032, 1129445, 163081, '<td valign="top">very nice composition. It''s a perfect shot. Expect this to score high. an 8 from me.</td>', 'very nice composition. It''s a perfect shot. Expect this to score high. an 8 from me.', '2014-09-11 12:12:53.000000', NULL, 1),
(7262033, 1129493, 163081, '<td valign="top">Excellent and nice mastering of shadows. The fork maybe should be brighter or shinny. A 7 from me.</td>', 'Excellent and nice mastering of shadows. The fork maybe should be brighter or shinny. A 7 from me.', '2014-09-11 12:14:39.000000', NULL, 1),
(7262035, 1129431, 163081, '<td valign="top">why did you crop out the shadow of the girls head?  I love this composition very much. an 8 from me</td>', 'why did you crop out the shadow of the girls head?  I love this composition very much. an 8 from me', '2014-09-11 12:17:03.000000', NULL, 1),
(7262045, 1129381, 100831, '<td valign="top">clever.</td>', 'clever.', '2014-09-11 13:47:34.000000', NULL, 1),
(7262046, 1129510, 100831, '<td valign="top">bear and moon. sweet love.</td>', 'bear and moon. sweet love.', '2014-09-11 13:48:47.000000', NULL, 1),
(7262125, 1129510, 6519, '<td valign="top">Came back to have another close study, but I''m still not a fan, sorry.</td>', 'Came back to have another close study, but I''m still not a fan, sorry.', '2014-09-11 17:53:43.000000', NULL, 1),
(7262126, 1129093, 6519, '<td valign="top">I am sorry, but this is just BORING. Nothing to recognize, nothing to look at, nothing to hold my attention. Boring, fuzzy, non-sensical, pointless.<br/> <br/>Good luck if you were going for the "brown ribbon".</td>', 'I am sorry, but this is just BORING. Nothing to recognize, nothing to look at, nothing to hold my attention. Boring, fuzzy, non-sensical, pointless. Good luck if you were going for the "brown ribbon".', '2014-09-11 17:54:06.000000', NULL, 1),
(7262127, 1129515, 6519, '<td valign="top">I''m trying to understand this, but there is so much going on and the colours are odd. Very confusing......</td>', 'I''m trying to understand this, but there is so much going on and the colours are odd. Very confusing......', '2014-09-11 17:57:53.000000', NULL, 1),
(7262128, 1129509, 6519, '<td valign="top">Actually, that is a silhouette (or mostly so) ..... not the same as a shadow. Pleasant enough image, but no shadows.</td>', 'Actually, that is a silhouette (or mostly so) ..... not the same as a shadow. Pleasant enough image, but no shadows.', '2014-09-11 17:59:00.000000', NULL, 1),
(7262129, 1129520, 6519, '<td valign="top">Quite wild, messy, distracting, loud......... and yet - there are actual shadows and a pleasing enough near-diagonal.</td>', 'Quite wild, messy, distracting, loud......... and yet - there are actual shadows and a pleasing enough near-diagonal.', '2014-09-11 18:01:13.000000', NULL, 1),
(7262130, 1129089, 6519, '<td valign="top">Sorry, but I have no clue what I am looking at. It isn''t interesting, it isn''t eye-candy. I see nothing that I can identify as "shadows". There may possibly BE shadows, but you failed to communicate this to me (and I really did try to make sense of this thing). 4.</td>', 'Sorry, but I have no clue what I am looking at. It isn''t interesting, it isn''t eye-candy. I see nothing that I can identify as "shadows". There may possibly BE shadows, but you failed to communicate this to me (and I really did try to make sense of this thing). 4.', '2014-09-11 18:02:34.000000', NULL, 1),
(7262132, 1129380, 6519, '<td valign="top">This is not a very exciting photo. And yet, at least it is a real shadow, so you certainly get points for that!!!!</td>', 'This is not a very exciting photo. And yet, at least it is a real shadow, so you certainly get points for that!!!!', '2014-09-11 18:04:15.000000', NULL, 1),
(7262137, 1129445, 6519, '<td valign="top">Coming back to study the submissions again.<br/>I still really like this scene. I still like the b&amp;w.<br/> <br/>However, whilst there are plenty of areas of darkness (plus reflections), I don''t feel that is in the spirit of a challenge called "shadows". My personal preference would be to see an actual shadow of something, not just dark areas.</td>', 'Coming back to study the submissions again.I still really like this scene. I still like the b&w. However, whilst there are plenty of areas of darkness (plus reflections), I don''t feel that is in the spirit of a challenge called "shadows". My personal preference would be to see an actual shadow of something, not just dark areas.', '2014-09-11 18:09:33.000000', NULL, 1),
(7262139, 1129516, 6519, '<td valign="top">Coming back for another study......<br/>I do see darkness here, i.e. under-exposed areas of your image. However, I still think that isn''t what a challenge called "shadows" is meant to be about. <br/>Good job with the HDR aspect of the situation, there are such extreme contrasts here that you had to deal with.</td>', 'Coming back for another study......I do see darkness here, i.e. under-exposed areas of your image. However, I still think that isn''t what a challenge called "shadows" is meant to be about. Good job with the HDR aspect of the situation, there are such extreme contrasts here that you had to deal with.', '2014-09-11 18:12:29.000000', NULL, 1),
(7262143, 1129487, 6519, '<td valign="top">Coming back for another look.... <br/>I still like this one a lot! You seem to be shooting straight into the sun, yet you managed to keep details on the gravestones instead of pure silhouettes, and all that without an obvious HDR look. The shadows are a strong feature. Very interesting image.</td>', 'Coming back for another look.... I still like this one a lot! You seem to be shooting straight into the sun, yet you managed to keep details on the gravestones instead of pure silhouettes, and all that without an obvious HDR look. The shadows are a strong feature. Very interesting image.', '2014-09-11 18:20:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7262531, 1129520, 170281, '<td valign="top">I really like how you rotated the photo to make it look like shadows on a wall.  Very creative and nicely done.</td>', 'I really like how you rotated the photo to make it look like shadows on a wall.  Very creative and nicely done.', '2014-09-12 14:50:00.000000', NULL, 1),
(7262532, 1129509, 170281, '<td valign="top">I like the photo but I think it missed the theme a bit.  I see more translucent silhouette versus shadow.</td>', 'I like the photo but I think it missed the theme a bit.  I see more translucent silhouette versus shadow.', '2014-09-12 14:53:12.000000', NULL, 1),
