(7262673, 1129441, 100831, '<td valign="top">Right on time:)</td>', 'Right on time:)', '2014-09-13 11:27:41.000000', NULL, 1),
(7262676, 1129274, 19825, '<td valign="top">Excellent lines and shadows.</td>', 'Excellent lines and shadows.', '2014-09-13 12:06:31.000000', NULL, 1),
(7262677, 1129185, 19825, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2014-09-13 12:06:58.000000', NULL, 1),
(7262678, 1129502, 19825, '<td valign="top">Splendidly captured and processed.</td>', 'Splendidly captured and processed.', '2014-09-13 12:07:38.000000', NULL, 1),
(7262707, 1129446, 68503, '<td valign="top">This is really cool and my top pick, hope its doing well for you.</td>', 'This is really cool and my top pick, hope its doing well for you.', '2014-09-13 12:51:13.000000', NULL, 1),
(7262708, 1129421, 68503, '<td valign="top">Great angle on this one!</td>', 'Great angle on this one!', '2014-09-13 12:53:28.000000', NULL, 1),
(7262709, 1129452, 68503, '<td valign="top">this has a lot of potential but I think it should have been cropped a little more on the left and right to get rid of the photographer and the roof unit. It may even be interesting to see what it looked like rotated left 90 degrees for a portrait. Still a decent job IMO</td>', 'this has a lot of potential but I think it should have been cropped a little more on the left and right to get rid of the photographer and the roof unit. It may even be interesting to see what it looked like rotated left 90 degrees for a portrait. Still a decent job IMO', '2014-09-13 12:57:09.000000', NULL, 1),
(7262710, 1129472, 68503, '<td valign="top">Im not really sure what Im looking at but I like it. It probably doesnt fit the challenge very well because its hard to make out what it is, but it made me stop to look and ponder. The lighter background looks like a dog or wolf with the circle object being his eye and the substance of him is made from mystical. Whatever it is it made for a unique image :)</td>', 'Im not really sure what Im looking at but I like it. It probably doesnt fit the challenge very well because its hard to make out what it is, but it made me stop to look and ponder. The lighter background looks like a dog or wolf with the circle object being his eye and the substance of him is made from mystical. Whatever it is it made for a unique image :)', '2014-09-13 13:01:14.000000', NULL, 1),
(7262802, 1129317, 113411, '<td valign="top">I would have given you a 10 but the black spot in the lower right hand corner catches my eye. Also the dust spot just below the black stand is a distraction ...other than that a 9!</td>', 'I would have given you a 10 but the black spot in the lower right hand corner catches my eye. Also the dust spot just below the black stand is a distraction ...other than that a 9!', '2014-09-13 19:23:12.000000', NULL, 1),
(7262896, 1129491, 58634, '<td valign="top">The shadow here creates a beautiful geometry in this image. I like it very much.</td>', 'The shadow here creates a beautiful geometry in this image. I like it very much.', '2014-09-14 15:17:08.000000', NULL, 1),
(7262897, 1129468, 58634, '<td valign="top">All in all a wonderful image.. although it almost looks more like a silhouette..</td>', 'All in all a wonderful image.. although it almost looks more like a silhouette..', '2014-09-14 15:17:40.000000', NULL, 1),
(7262898, 1129298, 58634, '<td valign="top">Such simple shadow but yet highly effective and creates a beautiful scenery that makes me want to take a walk downtown.. <br/> <br/>I''m assuming this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a> because this resembles his amazing work, and if not then take t hat as a high compliment.</td>', 'Such simple shadow but yet highly effective and creates a beautiful scenery that makes me want to take a walk downtown..  I''m assuming this is  jagar because this resembles his amazing work, and if not then take t hat as a high compliment.', '2014-09-14 15:25:19.000000', NULL, 1),
(7262899, 1129493, 58634, '<td valign="top">I really enjoy the texture here. The composition is also fantastic and really puts a good emphasis on the subject. I like the fact that the shadow is so different thant the actual subject. Great image.</td>', 'I really enjoy the texture here. The composition is also fantastic and really puts a good emphasis on the subject. I like the fact that the shadow is so different thant the actual subject. Great image.', '2014-09-14 15:26:00.000000', NULL, 1),
(7262900, 1129469, 58634, '<td valign="top">Gorgeous portrait. The shadows really enhance and add an unexplainable beauty to her face.</td>', 'Gorgeous portrait. The shadows really enhance and add an unexplainable beauty to her face.', '2014-09-14 15:27:20.000000', NULL, 1),
(7262901, 1129431, 58634, '<td valign="top">Fantastic concept. The shadows are certainly creepy and just looking at this gives me that creep factor that I am sure you were going for. Great composition and overall feel.</td>', 'Fantastic concept. The shadows are certainly creepy and just looking at this gives me that creep factor that I am sure you were going for. Great composition and overall feel.', '2014-09-14 15:28:06.000000', NULL, 1),
(7262932, 1129431, 152252, '<td valign="top">Wonderful creativity.</td>', 'Wonderful creativity.', '2014-09-14 18:30:14.000000', NULL, 1),
(7263058, 1129461, 156466, '<td valign="top">Would like to see the shadow more predominant.</td>', 'Would like to see the shadow more predominant.', '2014-09-15 08:19:32.000000', NULL, 1),
(7263060, 1129513, 156466, '<td valign="top">Stunning.  I hate that my monitor will not display the vertical in its entirety, so for this reason I''m wishing it was a little wider.</td>', 'Stunning.  I hate that my monitor will not display the vertical in its entirety, so for this reason I''m wishing it was a little wider.', '2014-09-15 08:21:05.000000', NULL, 1),
(7263061, 1129509, 156466, '<td valign="top">Technically a silhouette, not a shadow.</td>', 'Technically a silhouette, not a shadow.', '2014-09-15 08:21:37.000000', NULL, 1),
(7263065, 1129357, 156466, '<td valign="top">Nice idea that I''ve seen done a lot.  Not crazy about the angle and crop.  This crop accentuates the shadow (good) but not in a way that makes it visually pleasing (bad).  Different camera angle to the wheelchair?</td>', 'Nice idea that I''ve seen done a lot.  Not crazy about the angle and crop.  This crop accentuates the shadow (good) but not in a way that makes it visually pleasing (bad).  Different camera angle to the wheelchair?', '2014-09-15 08:23:48.000000', NULL, 1),
(7263066, 1129493, 156466, '<td valign="top">Exceptional.</td>', 'Exceptional.', '2014-09-15 08:24:22.000000', NULL, 1),
(7263069, 1129431, 156466, '<td valign="top">Well lit.  Not a fan of the skin tonality.</td>', 'Well lit.  Not a fan of the skin tonality.', '2014-09-15 08:26:15.000000', NULL, 1),
(7263070, 1129291, 156466, '<td valign="top">Shot with one hand holding the flower with the other?  Been there.  Need to work on getting your hand shadow out of the frame.</td>', 'Shot with one hand holding the flower with the other?  Been there.  Need to work on getting your hand shadow out of the frame.', '2014-09-15 08:27:02.000000', NULL, 1),
(7263072, 1129317, 156466, '<td valign="top">I like it, but not the choice to go lighter with the shadow than the subject.</td>', 'I like it, but not the choice to go lighter with the shadow than the subject.', '2014-09-15 08:27:45.000000', NULL, 1),
(7263079, 1129430, 156466, '<td valign="top">Interesting shadow, but the overall composition, not so much.  A little space to the left of the "cowboy" and maybe more of the dog''s legs (rotate clockwise a bit?) might have improved it.</td>', 'Interesting shadow, but the overall composition, not so much.  A little space to the left of the "cowboy" and maybe more of the dog''s legs (rotate clockwise a bit?) might have improved it.', '2014-09-15 08:34:59.000000', NULL, 1),
(7263082, 1129511, 156466, '<td valign="top">Cool shadow, but the diverging horizontals make me want at least one of them to be parallel to the frame (is it a sloping sidewalk or a crooked spackle line?).</td>', 'Cool shadow, but the diverging horizontals make me want at least one of them to be parallel to the frame (is it a sloping sidewalk or a crooked spackle line?).', '2014-09-15 08:36:48.000000', NULL, 1),
(7263084, 1129421, 156466, '<td valign="top">Nice capture but that angled line in the cement is killing me.  I''d personally have removed it in post, risked the DQ and fought like mad with the judges that it''s "power line distracting", but I get why you might not.  Otherwise excellent.</td>', 'Nice capture but that angled line in the cement is killing me.  I''d personally have removed it in post, risked the DQ and fought like mad with the judges that it''s "power line distracting", but I get why you might not.  Otherwise excellent.', '2014-09-15 08:38:46.000000', NULL, 1),
(7263085, 1129486, 156466, '<td valign="top">Would like it more if he was facing into the frame.  Not my favorite B&amp;W tone either.  Still an excellent shot.</td>', 'Would like it more if he was facing into the frame.  Not my favorite B&W tone either.  Still an excellent shot.', '2014-09-15 08:39:49.000000', NULL, 1),
(7263086, 1129089, 156466, '<td valign="top">Great photo, but I''m having difficulty understanding the "shadow" in it, and I know what a centerlock is.</td>', 'Great photo, but I''m having difficulty understanding the "shadow" in it, and I know what a centerlock is.', '2014-09-15 08:48:17.000000', NULL, 1),
(7263087, 1129185, 156466, '<td valign="top">Nicely captured and processed.  It feels like it has a but of a left rotation to it.  I had to do a screen capture and check and sure enough, 1-2 degrees to the right "feels" better.  Still a very good image.</td>', 'Nicely captured and processed.  It feels like it has a but of a left rotation to it.  I had to do a screen capture and check and sure enough, 1-2 degrees to the right "feels" better.  Still a very good image.', '2014-09-15 08:51:11.000000', NULL, 1),
(7263089, 1129437, 156466, '<td valign="top">Verticals are all skewed to the sides.  Hot spot from the light source off the cover.</td>', 'Verticals are all skewed to the sides.  Hot spot from the light source off the cover.', '2014-09-15 08:52:15.000000', NULL, 1),
(7263091, 1129426, 156466, '<td valign="top">Nicely done, but I might have burned the dragonfly shadow  and the muted stem shadow in a bit to better blend the shadows, despite the bright spot.</td>', 'Nicely done, but I might have burned the dragonfly shadow  and the muted stem shadow in a bit to better blend the shadows, despite the bright spot.', '2014-09-15 08:54:37.000000', NULL, 1),
(7263094, 1129452, 156466, '<td valign="top">This photographer''s soul needs saving.  I think it should have been rotated left because the composition doesn''t work for me at all.  Plus you''ve got bits of stuff poking out from both sides that do nothing but distract.</td>', 'This photographer''s soul needs saving.  I think it should have been rotated left because the composition doesn''t work for me at all.  Plus you''ve got bits of stuff poking out from both sides that do nothing but distract.', '2014-09-15 08:56:28.000000', NULL, 1),
(7263096, 1129373, 156466, '<td valign="top">Nice photo, but for this challenge I would expect the shadows to be as much the subject and not just there.</td>', 'Nice photo, but for this challenge I would expect the shadows to be as much the subject and not just there.', '2014-09-15 08:57:44.000000', NULL, 1),
(7263098, 1129216, 156466, '<td valign="top">There are some cool shadows that you could have played with here, but in the overall composition I don''t want to see any of them, I just want to look at the tower.  Had you played off the top of the tower OR the steps you could have had something very cool.  As is, it''s a nice picture, but not for this challenge.</td>', 'There are some cool shadows that you could have played with here, but in the overall composition I don''t want to see any of them, I just want to look at the tower.  Had you played off the top of the tower OR the steps you could have had something very cool.  As is, it''s a nice picture, but not for this challenge.', '2014-09-15 08:59:47.000000', NULL, 1),
(7263100, 1129186, 156466, '<td valign="top">Wish the shadows stood out just a touch more.  Not a lot, but just a little, particularly further from the light.  Still a wonderful capture.</td>', 'Wish the shadows stood out just a touch more.  Not a lot, but just a little, particularly further from the light.  Still a wonderful capture.', '2014-09-15 09:01:22.000000', NULL, 1),
(7263103, 1129446, 156466, '<td valign="top">Cool capture, but overall composition bothers me, particularly the way the shadows to the far right.  I''m thinking a square, or near square crop would have worked better, eliminating the left and right-most buildings.</td>', 'Cool capture, but overall composition bothers me, particularly the way the shadows to the far right.  I''m thinking a square, or near square crop would have worked better, eliminating the left and right-most buildings.', '2014-09-15 09:05:05.000000', NULL, 1),
(7263107, 1129520, 156466, '<td valign="top">Very cool use of rotation.  I think I might prefer a bit of a landscape crop here, but perhaps not.  Something just a little off compositionally (it feels that way anyway - I can''t tell you specifically).  Still, one of my favorites in this challenge.</td>', 'Very cool use of rotation.  I think I might prefer a bit of a landscape crop here, but perhaps not.  Something just a little off compositionally (it feels that way anyway - I can''t tell you specifically).  Still, one of my favorites in this challenge.', '2014-09-15 09:07:41.000000', NULL, 1),
(7263108, 1129474, 156466, '<td valign="top">Had you only moved that plant.</td>', 'Had you only moved that plant.', '2014-09-15 09:08:24.000000', NULL, 1),
(7263109, 1129503, 156466, '<td valign="top">Funny</td>', 'Funny', '2014-09-15 09:08:49.000000', NULL, 1),
(7263113, 1129465, 156466, '<td valign="top">Slightly skewed horizon and I wish you had capture the tip of the shadow.  Otherwise very nice.</td>', 'Slightly skewed horizon and I wish you had capture the tip of the shadow.  Otherwise very nice.', '2014-09-15 09:10:25.000000', NULL, 1),
(7263116, 1129459, 156466, '<td valign="top">Shadows work, lines don''t.</td>', 'Shadows work, lines don''t.', '2014-09-15 09:10:57.000000', NULL, 1),
(7263117, 1129391, 156466, '<td valign="top">Silhouettes are not shadows.</td>', 'Silhouettes are not shadows.', '2014-09-15 09:11:19.000000', NULL, 1),
(7263119, 1129455, 156466, '<td valign="top">Wish the shadows were as dominant as the silhouettes, and I wish the horizon was straight.</td>', 'Wish the shadows were as dominant as the silhouettes, and I wish the horizon was straight.', '2014-09-15 09:12:32.000000', NULL, 1),
(7263120, 1129093, 156466, '<td valign="top">Is that a request?</td>', 'Is that a request?', '2014-09-15 09:12:56.000000', NULL, 1),
(7263125, 1129282, 156466, '<td valign="top">Nicely captured.  I might have gone a little lighter on the wood tonality in the B&amp;W conversion.  Or maybe a little less heavy on the contrast.  Otherwise, outside of the bit of bush in the foreground I like it a lot.</td>', 'Nicely captured.  I might have gone a little lighter on the wood tonality in the B&W conversion.  Or maybe a little less heavy on the contrast.  Otherwise, outside of the bit of bush in the foreground I like it a lot.', '2014-09-15 09:14:53.000000', NULL, 1),
(7263127, 1129487, 156466, '<td valign="top">I love the shadows, particularly in the sky.  Just a tad over the top in the processing for me.  I almost wish this was less HDR-ish and showed lass of the details on the stones.  Really nice, but just a little heavy handed.  8 instead of a 10.</td>', 'I love the shadows, particularly in the sky.  Just a tad over the top in the processing for me.  I almost wish this was less HDR-ish and showed lass of the details on the stones.  Really nice, but just a little heavy handed.  8 instead of a 10.', '2014-09-15 09:16:53.000000', NULL, 1),
(7263129, 1129495, 156466, '<td valign="top">Oooooh, so close!!  Get those horizontal lines to run parallel to the bottom of the frame and this is a 10 for me.  Everything else is spot on perfect.  Wonderful capture.  8</td>', 'Oooooh, so close!!  Get those horizontal lines to run parallel to the bottom of the frame and this is a 10 for me.  Everything else is spot on perfect.  Wonderful capture.  8', '2014-09-15 09:21:00.000000', NULL, 1),
